    let category = "Flights";
    let selectedOption = null;
    let itinerary = [];
    let alertsEnabled = true;

    const tabs = document.querySelectorAll(".tab");
    const form = document.getElementById("searchForm");
    const results = document.getElementById("results");
    const destinations = document.getElementById("destinations");
    const overlay = document.getElementById("bookingOverlay");
    const modalContent = document.getElementById("modalContent");
    const categoryPhoto = document.getElementById("categoryPhoto");
    const categoryPhotoImage = document.getElementById("categoryPhotoImage");
    const categoryPhotoKicker = document.getElementById("categoryPhotoKicker");
    const categoryPhotoTitle = document.getElementById("categoryPhotoTitle");
    const categoryPhotoText = document.getElementById("categoryPhotoText");

    function updateCategoryPhoto() {
      const photo = categoryImages[category];
      if (!photo) return;
      categoryPhotoImage.src = photo.src;
      categoryPhotoImage.alt = `${category} travel photo`;
      categoryPhotoKicker.textContent = `LIVE ${category.toUpperCase()} PHOTO`;
      categoryPhotoTitle.textContent = photo.title;
      categoryPhotoText.textContent = photo.text;
    }

    // Set the date inputs to today and one week from today.
    const today = new Date();
    const nextWeek = new Date();
    nextWeek.setDate(today.getDate() + 7);

    function toDateInputValue(date) {
      const localDate = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
      return localDate.toISOString().slice(0, 10);
    }

    document.getElementById("departInput").value = toDateInputValue(today);
    document.getElementById("returnInput").value = toDateInputValue(nextWeek);
    updateCategoryPhoto();

    tabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        category = tab.dataset.category;
        tabs.forEach((item) => {
          const active = item === tab;
          item.classList.toggle("active", active);
          item.setAttribute("aria-selected", String(active));
        });

        const isHotel = category === "Hotels";
        document.getElementById("fromGroup").hidden = isHotel;
        document.getElementById("fromLabel").textContent = category === "Cabs" ? "PICKUP" : "FROM";
        document.getElementById("toLabel").textContent =
          isHotel ? "DESTINATION" : category === "Cabs" ? "DROP-OFF" : "TO";
        document.getElementById("departLabel").textContent = isHotel ? "CHECK-IN" : "DEPARTURE";
        document.getElementById("returnLabel").textContent = isHotel ? "CHECK-OUT" : "RETURN";

        results.hidden = true;
        destinations.hidden = false;
        categoryPhoto.hidden = false;
        updateCategoryPhoto();
        document.getElementById("liveLabel").hidden = false;
        document.getElementById("sectionTitle").textContent = "A change of scenery.";
        document.getElementById("sectionDescription").textContent =
          "Little escapes, big memories. Where will you go?";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      showResults();
    });

    function showResults() {
      const items = travelOptions[category];
      updateCategoryPhoto();
      categoryPhoto.hidden = false;

      results.innerHTML = items.map((item, index) => `
        <article class="result-card">
          <div class="provider-icon">${item.icon}</div>
          <div class="result-details">
            <span class="badge ${index === 0 ? "green" : ""}">
              ${index === 0 ? "BEST MATCH" : index === 1 ? "POPULAR" : "LOWEST PRICE"}
            </span>
            <h3>${item.name}</h3>
            <p>${item.detail}</p>
          </div>
          <div class="result-time">${item.time}</div>
          <div class="result-cost">
            <strong>$${item.price}</strong>
            <span>${category === "Hotels" ? "per night" : "per person"}</span>
          </div>
          <button class="book-button" data-index="${index}">Select</button>
        </article>
      `).join("");

      results.querySelectorAll(".book-button").forEach((button) => {
        button.addEventListener("click", () => openCheckout(items[Number(button.dataset.index)]));
      });

      destinations.hidden = true;
      results.hidden = false;
      document.getElementById("liveLabel").hidden = false;
      document.getElementById("sectionTitle").textContent = `Compare ${category.toLowerCase()}`;
      document.getElementById("sectionDescription").textContent =
        `Options for your trip to ${document.getElementById("toInput").value || "your destination"}.`;
    }

    function openCheckout(option) {
      selectedOption = option;
      modalContent.innerHTML = `
        <div class="eyebrow">SECURE CHECKOUT</div>
        <h2 id="modalTitle">Review your booking</h2>
        <div class="checkout-item">
          <span class="provider-icon">${option.icon}</span>
          <div><strong>${option.name}</strong><small>${option.detail}</small></div>
        </div>
        <div class="checkout-total"><span>Total</span><strong>$${option.price}</strong></div>
        <label class="payment-label" for="paymentMethod">Payment method</label>
        <select class="payment-select" id="paymentMethod">
          <option>Credit or debit card</option>
          <option>UPI</option>
          <option>Apple Pay</option>
          <option>PayPal</option>
        </select>
        <div class="upi-qr" id="upiQr" hidden>
          <div class="upi-qr-title">Scan to pay with UPI</div>
          <img src="data:image/png;base64," alt="UPI payment QR code" />
          <div class="upi-qr-note">Open your UPI app and scan this QR code.</div>
        </div>
        <p class="demo-note">Demo checkout — no payment will be charged.</p>
        <button class="confirm-button" id="confirmBooking">Confirm booking · $${option.price}</button>
      `;

      overlay.hidden = false;

      const paymentMethod = document.getElementById("paymentMethod");
      const upiQr = document.getElementById("upiQr");

      function updatePaymentMethod() {
        upiQr.hidden = paymentMethod.value !== "UPI";
      }

      paymentMethod.addEventListener("change", updatePaymentMethod);
      updatePaymentMethod();

      document.getElementById("confirmBooking").addEventListener("click", confirmBooking);
    }

    function confirmBooking() {
      const bookingId = "WF-" + Math.random().toString(36).slice(2, 8).toUpperCase();
      const paymentMethod = document.getElementById("paymentMethod")?.value || "Credit or debit card";
      const from = document.getElementById("fromInput").value || "—";
      const to = document.getElementById("toInput").value || "—";
      const departure = document.getElementById("departInput").value || "—";
      const returnDate = document.getElementById("returnInput").value || "—";
      const travelers = document.getElementById("travelersInput").value || "1 traveler";

      itinerary.push({
        ...selectedOption,
        category,
        bookingId,
        destination: to,
        from,
        departure,
        returnDate,
        travelers,
        paymentMethod
      });
      renderItinerary();

      modalContent.innerHTML = `
        <div class="success-mark">✓</div>
        <div class="eyebrow">BOOKING CONFIRMED</div>
        <h2 id="modalTitle">You’re all set.</h2>
        <p><strong>${selectedOption.name}</strong> has been added to your itinerary.</p>
        <div class="reference">Confirmation number <strong>${bookingId}</strong></div>
        <p class="confirmation-alert">
          ✦ ${alertsEnabled
            ? "Travel alerts are on for this booking."
            : "Turn on travel alerts in your itinerary for updates."}
        </p>
        <div style="display:grid;gap:8px;">
          <button class="confirm-button" id="downloadPdfButton">Download trip details PDF</button>
          <button class="confirm-button" id="doneButton" style="background:#eef2eb;color:#1d584b;">View my itinerary</button>
        </div>
      `;

      document.getElementById("downloadPdfButton").addEventListener("click", () => {
        generateTripPDF({
          bookingId,
          option: selectedOption,
          category,
          from,
          to,
          departure,
          returnDate,
          travelers,
          paymentMethod
        });
      });

      document.getElementById("doneButton").addEventListener("click", () => {
        overlay.hidden = true;
        document.getElementById("itinerary").scrollIntoView({ behavior: "smooth" });
      });
    }

    function generateTripPDF(details) {
      // Built-in PDF generator: no external libraries or internet connection required.
      // This creates a simple, valid A4 PDF and triggers a real file download.
      const clean = (value) => String(value ?? "")
        .replace(/[–—]/g, "-")
        .replace(/[“”]/g, '"')
        .replace(/[‘’]/g, "'")
        .replace(/✓/g, "OK")
        .replace(/✦/g, "*")
        .replace(/[^\x20-\x7E]/g, "");

      const wrap = (text, maxChars = 88) => {
        const words = clean(text).split(/\s+/);
        const lines = [];
        let line = "";
        words.forEach((word) => {
          if (!word) return;
          const candidate = line ? `${line} ${word}` : word;
          if (candidate.length > maxChars && line) {
            lines.push(line);
            line = word;
          } else {
            line = candidate;
          }
        });
        if (line) lines.push(line);
        return lines.length ? lines : [""];
      };

      const lines = [
        "WAYFARE. - YOUR TRIP DETAILS",
        "",
        "BOOKING CONFIRMED",
        `Confirmation number: ${details.bookingId}`,
        `Booked item: ${details.option.name}`,
        "",
        `Type: ${details.category}`,
        `From / Pickup: ${details.from}`,
        `To / Destination: ${details.to}`,
        `${details.category === "Hotels" ? "Check-in" : "Departure"}: ${formatPdfDate(details.departure)}`,
        `${details.category === "Hotels" ? "Check-out" : "Return"}: ${formatPdfDate(details.returnDate)}`,
        `Travelers: ${details.travelers}`,
        `Provider / Option: ${details.option.name}`,
        `Details: ${details.option.detail}`,
        `Time / Pickup: ${details.option.time}`,
        `Payment method: ${details.paymentMethod}`,
        `Total: $${details.option.price}`,
        "",
        `Travel alerts: ${alertsEnabled ? "ON" : "OFF"}`,
        "Demo booking confirmation generated by Wayfare."
      ];

      const bodyLines = [];
      lines.forEach((line) => bodyLines.push(...wrap(line)));

      // PDF text stream with simple line-by-line Helvetica text.
      const pageW = 595;
      const pageH = 842;
      const margin = 48;
      const fontSize = 11;
      const lineHeight = 16;

      let y = pageH - 55;
      const content = [];
      content.push("BT");
      content.push("/F1 18 Tf");
      content.push(`${margin} ${y} Td`);
      content.push(`(${escapePdfText(bodyLines[0])}) Tj`);
      content.push(`/F1 ${fontSize} Tf`);

      for (let i = 1; i < bodyLines.length; i++) {
        y -= lineHeight;
        if (y < 50) break;
        content.push(`0 -${lineHeight} Td`);
        content.push(`(${escapePdfText(bodyLines[i])}) Tj`);
      }
      content.push("ET");

      const stream = content.join("\n");
      const objects = [];
      objects.push("<< /Type /Catalog /Pages 2 0 R >>");
      objects.push("<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
      objects.push(
        `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageW} ${pageH}] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>`
      );
      objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
      objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);

      let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
      const offsets = [0];

      objects.forEach((obj, index) => {
        offsets.push(pdf.length);
        pdf += `${index + 1} 0 obj\n${obj}\nendobj\n`;
      });

      const xrefOffset = pdf.length;
      pdf += `xref\n0 ${objects.length + 1}\n`;
      pdf += "0000000000 65535 f \n";
      for (let i = 1; i <= objects.length; i++) {
        pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
      }
      pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\n`;
      pdf += `startxref\n${xrefOffset}\n%%EOF`;

      const blob = new Blob([pdf], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `Wayfare_Trip_${clean(details.bookingId) || "Details"}.pdf`;
      link.style.display = "none";
      document.body.appendChild(link);
      link.click();
      link.remove();

      setTimeout(() => URL.revokeObjectURL(url), 2000);
    }

    function escapePdfText(text) {
      return String(text)
        .replace(/\\/g, "\\\\")
        .replace(/\(/g, "\\(")
        .replace(/\)/g, "\\)");
    }

    function formatPdfDate(value) {
      if (!value || value === "—") return "—";
      const date = new Date(`${value}T00:00:00`);
      if (Number.isNaN(date.getTime())) return value;
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    }

    function renderItinerary() {
      document.getElementById("itemCount").textContent = itinerary.length;

      if (itinerary.length === 0) {
        document.getElementById("itineraryContent").innerHTML = `
          <div class="empty-itinerary">
            <div class="empty-icon">⌑</div>
            <strong>Your trip starts here</strong>
            <p>Book a flight, stay, or ride and it’ll show up here.</p>
          </div>`;
        return;
      }

      document.getElementById("itineraryContent").innerHTML = `
        <div class="itinerary-items">
          ${itinerary.map((item) => `
            <div class="itinerary-item">
              <span class="mini-icon">${item.icon}</span>
              <div>
                <strong>${item.name}</strong>
                <small>${item.category} · ${item.bookingId}</small>
              </div>
              <b>$${item.price}</b>
            </div>
          `).join("")}
        </div>`;
    }

    document.getElementById("alertToggle").addEventListener("click", function () {
      alertsEnabled = !alertsEnabled;
      this.classList.toggle("on", alertsEnabled);
      this.setAttribute("aria-pressed", String(alertsEnabled));
      document.getElementById("alertNote").hidden = !alertsEnabled;
    });

    document.getElementById("closeModal").addEventListener("click", () => {
      overlay.hidden = true;
    });

    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) overlay.hidden = true;
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") overlay.hidden = true;
    });
